L000402	\textit{Appendix B: Short-range operators}---the NMEs computed in this work are given by
L000403	\begin{align}
L000404	      M_{\alpha,\rm sd} =  \bigg\langle0_f^+ \bigg\| \sum_{m,n} O_\alpha^{mn}(\textbf{q})\bigg\|0_i^+\bigg\rangle
L000405	\end{align}
L000406	with the short-range $0\nu\beta\beta$-decay operators in momentum space,
L000407	\begin{align}
L000408	    O^{mn}_{\alpha} (\textbf{q})= \frac{R}{2\pi m_{\pi}^2} h_{\alpha}(\textbf{q}^2) S_\alpha (\textbf{q}) \tau^+_m \tau^+_n,
L000409	\end{align}
L000410	where $\alpha \in \{\rm F, GT, T\}$, $R=1.2A^{1/3}$ is the nuclear radius, $q$ is the momentum transfer between the nucleons $m$ and $n$, $\tau^+$ is the isospin-raising operator, and $m_\pi =  138.039$ MeV is the average pion mass. The factor $m_{\pi}^2$ was introduced to make the NMEs dimensionless and $\mathcal{O}(1)$ to correspond to the $\chi$EFT power counting~\cite{MasterFormula}. Note that this differs from the convention used in the literature~\cite{Menendez2018,Horoi2016,Faessler2014,Fang2018,Hyvarinen2015,Barea2015,Rodriguez2010}, by a factor of $m_{\rm p}m_{\rm e}/m_{\pi}^2$. The spin-spatial part of the operators, $S_\alpha(\textbf{q})$, is given by
L000411	\begin{align}
L000412	    S_{\rm F} (\textbf{q}) &= \mathbbm{1},\\
L000413	    S_{\rm GT} (\textbf{q}) &= \boldsymbol{\sigma}_{m} \cdot \boldsymbol{\sigma}_{n},\\
L000414	    S_{\rm T}(\textbf{q}) &= -3 \frac{(\boldsymbol{\sigma}_m\cdot \textbf{q})(\boldsymbol{\sigma}_n\cdot \textbf{q})}{q^2} + \boldsymbol{\sigma}_{m} \cdot \boldsymbol{\sigma}_{n},
L000415	\end{align}
L000416	where $\boldsymbol{\sigma}$ are the Pauli matrices. The neutrino potentials $h_\alpha(\textbf{q}^2)$ are defined as
L000417	\begin{align}
L000418	     h_{\rm F}(\textbf{q}^2) &= g_{\rm V}(\textbf{q}^2),\\
L000419	     h_{\rm GT}(\textbf{q}^2)&=h_{\rm GT}^{\rm AA}(\textbf{q}^2)+h_{\rm GT}^{\rm AP}(\textbf{q}^2)+h_{\rm GT}^{\rm PP}(\textbf{q}^2)+h_{\rm GT}^{\rm MM}(\textbf{q}^2),\\
L000420	     h_{\rm T}(\textbf{q}^2)&=h_{\rm T}^{\rm AP}(\textbf{q}^2)+h_{\rm T}^{\rm PP}(\textbf{q}^2)+h_{\rm T}^{\rm MM}(\textbf{q}^2),
L000421	\end{align}
L000422	where the different components are defined as
L000423	\begin{align}
L000424	    h_{\rm GT}^{\rm AA}(\textbf{q}^2) &= h_{\rm T}^{\rm AA}(\textbf{q}^2) = \frac{g_{\rm A}^2(\textbf{q}^2)}{g_{\rm A}^2},\label{np1}\\
L000425	    h_{\rm GT}^{\rm AP}(\textbf{q}^2) &= -h_{\rm T}^{\rm AP}(\textbf{q}^2)=\frac{g_{\rm P}(\textbf{q}^2)}{g_{\rm A}^2} g_{\rm A}(\textbf{q}^2)\frac{\textbf{q}^2}{3m_{\rm nucl}},\label{np2}\\
L000426	    h_{\rm GT}^{\rm PP}(\textbf{q}^2) &= -h_{\rm T}^{\rm PP}(\textbf{q}^2)=\frac{g_{\rm P}^2(\textbf{q}^2)}{g_{\rm A}^2}\frac{\textbf{q}^4}{12m_{\rm nucl}^2},\label{np3}\\
L000427	    h_{\rm GT}^{\rm MM}(\textbf{q}^2) &= 2h_{\rm T}^{\rm MM}(\textbf{q}^2) = g_{\rm M}^2(\textbf{q}^2) \frac{\textbf{q}^2}{6g_{\rm A}^2 m_{\rm nucl}^2}\label{np4} ,
L000428	\end{align}
L000429	with the average nucleon mass $m_{\rm nucl} = 938.919$ MeV and the vector, axial-vector, induced pseudo-scalar and weak-magnetism coupling constants $g_{\rm V},\  g_{\rm A}, \ g_{\rm P}$ and $g_{\rm M}$. We assume $g_{\rm P}(\textbf{q}^2)$ and $g_{\rm M}(\textbf{q}^2)$ are given by
L000430	\begin{align}
L000431	    g_{\rm P}(\textbf{q}^2) &= -\frac{2m_{\rm nucl} g_{\rm A}(\textbf{q}^2)}{\textbf{q}^2 + m_\pi^2},\\
L000432	    g_{\rm M}(\textbf{q}^2) &= (1+\kappa_1) g_{\rm V}(\textbf{q}^2)
L000433	\end{align}
L000434	where $\kappa_1 = 3.7$ is the anomalous
L000435	isovector nucleon magnetic moment. The potentials $h_{\rm GT}^{\rm MM}(\textbf{q}^2)$ and $h_{\rm T}^{\rm MM}(\textbf{q}^2)$ are uniquely suppressed by $\textbf{q}^2/m_{\rm nucl}^2$ relative to other potentials, but this suppression is reduced by the factor $(1+\kappa_1)^2 \sim 22$. This enhancement is generic to both long- and short-range operators, however there is additional enhancement unique to short-range operators coming from  the suppression factor $\textbf{q}^2/m_{\rm nucl}^2$ being larger for short-range operators due to larger momentum transfers.
L000436	
L000437	
L000438	When we use the dipole parameterization of the vector and axial form factors, we have~\cite{MasterFormula}
L000439	\begin{align}
L000440	      g_{\rm V}(\textbf{q}^2) &= g_{\rm V}\left(1+\frac{\textbf{q}^2}{\Lambda^2_{\rm V} }\right)^{-2}, \\ g_{\rm A}(\textbf{q}^2) &= g_{\rm A} \left(1+\frac{\textbf{q}^2}{\Lambda^2_{\rm A}}\right)^{-2}
L000441	\end{align}
L000442	with $\Lambda_{\rm V} = 850$ MeV and $\Lambda_{\rm A} = 1086$ MeV.
L000443	
L000444	In an EFT framework, dipole form factors for the vector, axial and magnetic currents are not leading order and resum only a subset of higher-order contributions, thus providing no systematic improvement when applied to leading-order operators \cite{Cirigliano2018a}.
L000445	While the $\textbf{q}^2$-dependence arising from the pion pole in the pseudoscalar form factor is genuinely leading order, promoting $g_\text{V}\!\to\! g_\text{V}(\textbf{q}^2)$ or $g_\text{A}\!\to\!g_\text{A}(\textbf{q}^2)$ is not justified.
L000446	Therefore, in this work we retain only leading-order constants in the vector and axial currents and regulate the operator consistently with the interaction. In other words, we have
L000447	\begin{align}
L000448	    g_{\rm V}(\textbf{q}^2) &=g_\text{V} ,\label{eqs:gv}\\
L000449	    g_{\rm A}(\textbf{q}^2) &= g_{\rm A} \label{eqs:ga}
L000450	\end{align}
L000451	where $g_\text{V}=1,\  g_\text{A} = 1.27$ and we include a local regulator function $f_\text{local}^\text{NN}(\textbf{q})$ multiplying each neutrino potential (Eqs. (\ref{np1}-\ref{np4})). Specifically, we multiply by
L000452	\begin{align}
L000453	    f_\text{local}^\text{NN} (\textbf{q}) &= \exp \left[-\left(\frac{\textbf{q}}{\Lambda}\right)^{2n}\right]
L000454	\end{align}
L000455	with $\Lambda = 500 $ MeV and $n = 3$ to be consistent with the N$^3$LO$_\text{LNL}$ interaction and $\Lambda = 394$ MeV and $n=4$ to be consistent with the $\Delta_\text{GO}$ interaction.
L000456	Using Eqs.~(\ref{eqs:gv}-\ref{eqs:ga}), we retain the leading-order pseudo-scalar and magnetic currents, $g_\text{P}(\textbf{q}^2)$ and $g_\text{M}(\textbf{q}^2)$, consistent in chiral perturbation theory.
